parameters.jsCode:
const people = ($input.first().json.people || []).filter(p => p.email);
const seen = new Set();
const out = [];
for (const p of people) { if (seen.has(p.email)) continue; seen.add(p.email);
  out.push({ json: { name: p.first_name||'', email: p.email, title: p.title||'', company: (p.organization&&p.organization.name)||'' } }); }
return out;

