const now = Date.now();
const rows = items.map(i => i.json).filter(r => (r.status||'').toLowerCase() !== 'converted');
const out = [];
for (const r of rows) {
  const step = parseInt(r.nurtureStep||'0', 10);
  const last = r.lastTouch ? Date.parse(r.lastTouch) : 0;
  const dueAfter = [0, 2, 5, 9][step] || null; // days between touches
  if (dueAfter === null) continue;
  if (!last || (now - last) / 86400000 >= dueAfter) out.push({ json: { ...r, nextStep: step + 1 } });
}
return out;

const now = Date.now();
const out = [];
for (const i of items) { const r = i.json;
  if ((r.status||'') === 'no-show') { out.push({ json: { ...r, action: 'rebook' } }); continue; }
  const start = r.startsAt ? Date.parse(r.startsAt) : 0;
  const hrs = (start - now) / 3600000;
  if (hrs > 23 && hrs <= 24 && r.reminded24 !== 'yes') out.push({ json: { ...r, action: 'remind' } });
}
return out;

const now=Date.now();
const catalog=($('Read Products').all()||[]).map(i=>i.json.name||i.json.product).filter(Boolean).join(', ');
return items.map(i=>i.json).filter(r=>r.email && (r.status||'')==='completed' && r.upsellSent!=='yes' && r.completedAt && (now-Date.parse(r.completedAt))/86400000<=14).map(r=>({json:{...r, catalog}}));

